// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != c.owner());
        // Attempt to call owned() as non-owner - should revert in reference
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.owned.selector));
        // The property: calling owned() by a non-owner must revert
        assertTrue(!ok);
    }
}

